#!/bin/bash
# Uninstall script for Unraid USB Creator
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Unraid USB Creator..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Unraid USB Creator if running..."
pkill -f "Unraid USB Creator" 2>/dev/null || true

# Remove /Applications/Unraid USB Creator.app
echo "Removing /Applications/Unraid USB Creator.app..."
if [ -d "/Applications/Unraid USB Creator.app" ]; then
    rm -rf "/Applications/Unraid USB Creator.app" 2>/dev/null || true
elif [ -f "/Applications/Unraid USB Creator.app" ]; then
    rm -f "/Applications/Unraid USB Creator.app" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/net.unraid.Unraid USB Creator.plist
echo "Removing $HOME/Library/Preferences/net.unraid.Unraid USB Creator.plist..."
if [ -d "$HOME/Library/Preferences/net.unraid.Unraid USB Creator.plist" ]; then
    rm -rf "$HOME/Library/Preferences/net.unraid.Unraid USB Creator.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/net.unraid.Unraid USB Creator.plist" ]; then
    rm -f "$HOME/Library/Preferences/net.unraid.Unraid USB Creator.plist" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
